func save_tree(name):
				var loadout = get_active_stats().mutation_tree_loadout
				if not loadout or not loadout.has("trees"):
								return false
				var current = get_current_tree()
				if not current:
								return false
				for tree in loadout.trees:
								if tree.name == name:
												tree.passives = current.passives.duplicate(true)
												emit_signal("passives_changed")
												return true
				loadout.trees.append({"name": name, "passives": current.passives.duplicate(true)})
				emit_signal("passives_changed")
				return true

func load_tree(name):
				var loadout = get_active_stats().mutation_tree_loadout
				if not loadout or not loadout.has("trees"):
								return false
				for tree in loadout.trees:
								if tree.name == name:
												loadout.active = name
												emit_signal("tree_changed")
												emit_signal("passives_changed")
												return true
				return false

func delete_tree(name):
				var loadout = get_active_stats().mutation_tree_loadout
				if not loadout or not loadout.has("trees"):
								return false
				for tree in loadout.trees:
								if tree.name == name:
												loadout.trees.erase(tree)
												if loadout.active == name:
																if len(loadout.trees) > 0:
																				loadout.active = loadout.trees[0].name
																else:
																				loadout.active = null
												emit_signal("tree_changed")
												emit_signal("passives_changed")
												return true
				return false

