func _migrate_mutation_tree_loadout(stats):
				var loadout = stats.mutation_tree_loadout
				if typeof(loadout) != TYPE_DICTIONARY:
								stats.mutation_tree_loadout = {"class": null, "active": null, "trees": []}
								loadout = stats.mutation_tree_loadout
				if not loadout.has("trees"):
								var passives = loadout.get("passives", [])
								loadout["trees"] = [{"name": "Tree 1", "passives": passives}]
				elif len(loadout.trees) == 0 and loadout.has("passives"):
								loadout.trees.append({"name": "Tree 1", "passives": loadout.passives})
				if loadout.has("passives"):
								loadout.erase("passives")
				for tree in loadout.trees:
								if not tree.has("name"):
												tree["name"] = "Tree 1"
								if not tree.has("passives"):
												tree["passives"] = []
				if not loadout.has("active") or loadout.active == null or loadout.active == "":
								if len(loadout.trees) > 0:
												loadout.active = loadout.trees[0].name
								else:
												loadout.active = null

